#!/usr/bin/env node
/**
 * Bundles userscript/main.ts (+ the capture logic of @ms365copilot/core it
 * shares with the browser extension) into ms365copilot-token.user.js, the
 * file users install in Tampermonkey/Violentmonkey.
 *
 *   node scripts/build-userscript.mjs           write the .user.js
 *   node scripts/build-userscript.mjs --check   exit 1 if it is out of date
 *
 * The generated file is committed (it is installed straight from GitHub and
 * auto-updates through @updateURL), so `pnpm build` regenerates it and the
 * tests run the --check: the userscript can no longer fall behind the
 * extension the way the hand-written one did.
 */
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { build } from 'tsdown';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const OUTPUT = join(ROOT, 'ms365copilot-token.user.js');
const REPO = 'https://github.com/cristiancastineiras/M365CopilotVSCode';
const RAW = 'https://raw.githubusercontent.com/cristiancastineiras/M365CopilotVSCode/main/extensiones/vscode/ms365copilot-token.user.js';
const MATCHES = [
	'https://m365.cloud.microsoft/*',
	'https://*.cloud.microsoft/*',
	'https://www.office.com/*',
	'https://outlook.office.com/*',
	'https://teams.microsoft.com/*',
];
const GRANTS = [
	'GM_getValue',
	'GM_setValue',
	'GM_addValueChangeListener',
	'GM_setClipboard',
	'GM_xmlhttpRequest',
	'GM_registerMenuCommand',
	'unsafeWindow',
];

function metadata(version) {
	const lines = [
		['name', 'M365 Copilot — token → VS Code'],
		['name:es', 'M365 Copilot — token → VS Code'],
		['namespace', REPO],
		['version', version],
		[
			'description',
			'Captures your Microsoft 365 Copilot session token and sends it to the M365 Copilot extension for VS Code automatically (or lets you copy it).',
		],
		[
			'description:es',
			'Captura el token de tu sesión de Microsoft 365 Copilot y lo envía a la extensión M365 Copilot de VS Code automáticamente (o te deja copiarlo).',
		],
		['author', 'Cristian Castineiras'],
		['homepageURL', REPO],
		['supportURL', `${REPO}/issues`],
		['updateURL', RAW],
		['downloadURL', RAW],
		['run-at', 'document-start'],
		...MATCHES.map((match) => ['match', match]),
		...GRANTS.map((grant) => ['grant', grant]),
		// The VS Code extension's local server (TOKEN_SERVER_URL in @ms365copilot/core).
		['connect', 'localhost'],
	];
	const width = Math.max(...lines.map(([key]) => key.length)) + 2;
	return [
		'// ==UserScript==',
		...lines.map(([key, value]) => `// @${key.padEnd(width - 1)}${value}`),
		'// ==/UserScript==',
		'',
		'// GENERATED by extensiones/vscode/scripts/build-userscript.mjs from userscript/main.ts',
		'// and @ms365copilot/core — do not edit by hand: run `pnpm build` in extensiones/vscode.',
		'',
	].join('\n');
}

export async function buildUserscript() {
	const { version } = JSON.parse(readFileSync(join(ROOT, 'package.json'), 'utf8'));
	const outDir = mkdtempSync(join(tmpdir(), 'ms365-userscript-'));
	try {
		await build({
			config: false,
			cwd: ROOT,
			entry: { userscript: join(ROOT, 'userscript', 'main.ts') },
			format: 'iife',
			platform: 'browser',
			target: 'es2020',
			outDir,
			dts: false,
			sourcemap: false,
			minify: false,
			clean: false,
			hash: false,
			logLevel: 'warn',
			tsconfig: join(ROOT, 'userscript', 'tsconfig.json'),
			deps: { alwaysBundle: ['@ms365copilot/core'] },
			banner: metadata(version),
		});
		const [file] = (await import('node:fs')).readdirSync(outDir).filter((name) => name.endsWith('.js'));
		return readFileSync(join(outDir, file), 'utf8').replace(/\r\n/g, '\n');
	} finally {
		rmSync(outDir, { recursive: true, force: true });
	}
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
	const fresh = await buildUserscript();
	if (process.argv.includes('--check')) {
		let current = '';
		try {
			current = readFileSync(OUTPUT, 'utf8').replace(/\r\n/g, '\n');
		} catch {
			/* missing counts as stale */
		}
		if (current !== fresh) {
			console.error('ms365copilot-token.user.js is out of date: run `pnpm build` in extensiones/vscode.');
			process.exit(1);
		}
		console.log('ms365copilot-token.user.js is up to date.');
	} else {
		writeFileSync(OUTPUT, fresh);
		console.log(`ms365copilot-token.user.js written (${Math.round(fresh.length / 1024)} KB).`);
	}
}
